import { getHttpHttpsAgents } from '../../utils/http-https-agents';
import type { GetHttpHttpsAgentsParams } from '../../utils/http-https-agents';

export type Agents = { httpAgent?: any; httpsAgent?: any };
export type ResolveAgents = (url: string) => Promise<Agents>;

// Proxy/TLS configuration for resolving HTTP(S) agents — the `getHttpHttpsAgents` input minus the
// per-request URL, which is supplied per call. This is the only network config secret-manager
// callers pass; `resolveAgents` stays an internal implementation detail of this package.
export type SecretManagerNetworkConfig = Omit<GetHttpHttpsAgentsParams, 'requestUrl'>;

// Turn a static network config into a per-URL agent resolver backed by the shared
// `getHttpHttpsAgents`. Callers (electron/CLI) supply only the config; the resolver never leaves
// this package.
export const buildResolveAgents = (networkConfig?: SecretManagerNetworkConfig): ResolveAgents => {
  return (url: string) => getHttpHttpsAgents({ requestUrl: url, ...(networkConfig as any) });
};
